def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: The timedelta instance to dehydrate.
    :type value: datetime.timedelta
    :return: A dictionary representation of the timedelta.
    :rtype: dict
    """
    if value is None:
        return None
    if not isinstance(value, timedelta):
        raise TypeError(f"Expected datetime.timedelta, got {type(value).__name__}")
    try:
        return {
            'days': value.days,
            'seconds': value.seconds,
            'microseconds': value.microseconds
        }
    except Exception as exc:
        raise ValueError(f"Failed to dehydrate timedelta: {exc}") from exc

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    # Handle None gracefully
    if value is None:
        return None

    # Ensure the value is a datetime.time instance
    # Avoid importing datetime by checking the class name and module
    cls = value.__class__
    if not (cls.__name__ == 'time' and cls.__module__ == 'datetime'):
        raise TypeError(f"Expected a datetime.time instance, got {type(value).__name__}")

    # Convert the time to an ISO 8601 string representation
    try:
        return value.isoformat()
    except Exception as exc:
        # If isoformat fails for some reason, fall back to manual formatting
        try:
            return f"{value.hour:02d}:{value.minute:02d}:{value.second:02d}"
        except Exception:
            raise ValueError("Unable to dehydrate time value") from exc

def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: Point
    :type value: Point
    :return: dict or None
    """
    try:
        if value is None:
            return None

        # If value is a dict with x, y, z keys
        if isinstance(value, dict):
            if all(k in value for k in ("x", "y", "z")):
                return {"x": value["x"], "y": value["y"], "z": value["z"]}

        # If value is a tuple or list of length 3
        if isinstance(value, (tuple, list)) and len(value) == 3:
            return {"x": value[0], "y": value[1], "z": value[2]}

        # If value has attributes x, y, z
        if hasattr(value, "x") and hasattr(value, "y") and hasattr(value, "z"):
            return {"x": getattr(value, "x"), "y": getattr(value, "y"), "z": getattr(value, "z")}

        # Try to iterate over value and extract three items
        try:
            it = iter(value)
            coords = [next(it), next(it), next(it)]
            # Ensure there are no more items
            try:
                next(it)
                raise TypeError
            except StopIteration:
                pass
            return {"x": coords[0], "y": coords[1], "z": coords[2]}
        except Exception:
            pass

        raise TypeError(f"Unsupported type for dehydrate_point: {type(value).__name__}")
    except Exception:
        # In case of any unexpected error, return None
        return None

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # If the instance itself behaves like a dict
        if isinstance(self, dict):
            return list(self.keys())
        # Common attribute names that may hold a dict-like structure
        for attr in ("_data", "data", "records", "items"):
            if hasattr(self, attr):
                val = getattr(self, attr)
                if isinstance(val, dict):
                    return list(val.keys())
                if hasattr(val, "keys") and callable(val.keys):
                    return list(val.keys())
        # Fallback: use the instance's __dict__, filtering out private attributes
        return [k for k in self.__dict__ if not k.startswith("_")]
    except Exception as exc:
        raise RuntimeError("Unable to retrieve record keys") from exc

