def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Ensure the object has a mutable byte sequence named 'data'
    if not hasattr(self, 'data'):
        raise AttributeError("The object does not have a 'data' attribute")
    data = self.data
    if not isinstance(data, (bytearray, list)):
        raise TypeError("'data' must be a mutable sequence of bytes (bytearray or list)")
    if len(data) < 2:
        raise ValueError("Not enough data to pop a 16-bit value (requires at least 2 bytes)")
    try:
        low = data.pop()   # least significant byte
        high = data.pop()  # most significant byte
    except Exception as exc:
        raise RuntimeError(f"Failed to pop bytes from data: {exc}") from exc
    # Validate popped byte values
    for byte_val, name in ((high, "high"), (low, "low")):
        if not isinstance(byte_val, int) or not (0 <= byte_val <= 0xFF):
            raise ValueError(f"Invalid byte value for {name}: {byte_val}")
    return (high << 8) | low

