def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate name
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Normalize fields
    if fields is None:
        fields = []
    if not hasattr(fields, "__iter__"):
        raise TypeError("fields must be an iterable of field names")
    field_names = []
    for f in fields:
        if not isinstance(f, str):
            raise TypeError("field names must be strings")
        if f in field_names:
            raise ValueError(f"duplicate field name: {f}")
        field_names.append(f)
    # Validate srid_map
    if srid_map is None:
        srid_map = {}
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")
    # Define the __init__ method for the new class
    def __init__(self, x, y, **kwargs):
        # Call the base Point constructor
        Point.__init__(self, x, y)
        # Set the dynamic fields
        for f in field_names:
            setattr(self, f, kwargs.pop(f, None))
        # Raise an error if unexpected keyword arguments were supplied
        if kwargs:
            unexpected = ", ".join(kwargs.keys())
            raise TypeError(f"unexpected keyword arguments: {unexpected}")
    # Define a helpful __repr__ method
    def __repr__(self):
        field_str = ", ".join(f"{f}={getattr(self, f)!r}" for f in field_names)
        base = f"{name}({self.x}, {self.y}"
        if field_str:
            base += ", " + field_str
        return base + ")"
    # Assemble the class dictionary
    attrs = {
        "__init__": __init__,
        "__repr__": __repr__,
        "srid_map": srid_map,
    }
    # Dynamically create the subclass of Point
    cls = type(name, (Point,), attrs)
    return cls

def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    if not isinstance(code, str):
        raise TypeError(f"Expected code to be a string, got {type(code).__name__}")
    # Default R options to set before executing user code
    r_options = [
        "options(stringsAsFactors = FALSE)",
        "options(digits = 10)",
        "options(warn = 2)",
    ]
    # If the provided code is empty or only whitespace, return just the options
    if not code.strip():
        return "\n".join(r_options)
    # Prepend the options to the user code
    return "\n".join(r_options + [code])

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")
    import re
    # Find all contiguous digit sequences and convert them to integers.
    parts = re.findall(r'\d+', s)
    return tuple(int(part) for part in parts)

