@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        # Helper to format a single exception (including its traceback)
        def _format_exc(exc):
            parts = []
            # Exception type and message
            exc_type = type(exc).__name__
            exc_msg = str(exc)
            # Traceback extraction
            tb = getattr(exc, "__traceback__", None)
            if tb is None:
                # No traceback available
                parts.append(f"{exc_type}: {exc_msg}")
                return "\n".join(parts)
            # Extract frames
            frames = []
            while tb and len(frames) < max_level:
                frame = tb.tb_frame
                lineno = tb.tb_lineno
                code = frame.f_code
                filename = code.co_filename
                func_name = code.co_name
                # Simplify filename path
                # Replace backslashes with forward slashes for uniformity
                norm_path = filename.replace("\\", "/")
                path_parts = norm_path.split("/")
                if len(path_parts) > max_path_level:
                    path_parts = path_parts[-max_path_level:]
                simplified_path = "/".join(path_parts)
                # Get line of code if available
                line = None
                try:
                    with open(filename, "r", encoding="utf-8") as f:
                        lines = f.readlines()
                        if 0 < lineno <= len(lines):
                            line = lines[lineno - 1].strip()
                except Exception:
                    line = None
                frames.append((simplified_path, lineno, func_name, line))
                tb = tb.tb_next
            # Build stack trace string
            for path, lineno, func, line in frames:
                parts.append(f'  File "{path}", line {lineno}, in {func}')
                if line:
                    parts.append(f"    {line}")
            parts.append(f"{exc_type}: {exc_msg}")
            return "\n".join(parts)

        # Handle nested exceptions (__cause__ and __context__)
        def _format_chain(exc):
            chain = []
            current = exc
            while current:
                chain.append(_format_exc(current))
                # Prefer __cause__ over __context__
                if getattr(current, "__cause__", None):
                    current = current.__cause__
                elif getattr(current, "__context__", None):
                    current = current.__context__
                else:
                    current = None
            return "\nCaused by:\n".join(chain)

        try:
            if not isinstance(e, BaseException):
                return str(e)
            return _format_chain(e)
        except Exception as err:
            # Fallback to simple string representation if formatting fails
            return f"Error formatting exception: {err}\nOriginal exception: {e}"

