def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        cls_name = self.__class__.__name__
    except Exception:
        return None
    for suffix in ("Py", "Fallback"):
        if cls_name.endswith(suffix):
            return cls_name[:-len(suffix)]
    return cls_name

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    if object is None:
        raise ValueError("object cannot be None")
    try:
        from zope.interface import directlyProvidedBy as _directlyProvidedBy
    except Exception as exc:
        raise RuntimeError("zope.interface is required for directlyProvidedBy") from exc
    try:
        return _directlyProvidedBy(object)
    except Exception as exc:
        raise ValueError(f"Cannot determine interfaces directly provided by {object!r}") from exc

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # Helper to recursively flatten tuples
    def _flatten(item, acc):
        if isinstance(item, tuple):
            for sub in item:
                _flatten(sub, acc)
        else:
            acc.append(item)

    if output is None:
        output = []
    elif not isinstance(output, list):
        raise TypeError("output must be a list or None")

    if sequence is None:
        return output

    # If sequence is not iterable (but not a string), treat as single element
    try:
        iter(sequence)
        is_iterable = True
    except TypeError:
        is_iterable = False

    if not is_iterable or isinstance(sequence, (str, bytes)):
        _flatten(sequence, output)
    else:
        for item in sequence:
            _flatten(item, output)

    return output

def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import os
        import sys
    except Exception:
        # If imports fail for some reason, default to not attempting C optimizations
        return False

    # 1. Detect PyPy
    try:
        if hasattr(sys, "implementation"):
            if getattr(sys.implementation, "name", "").lower() == "pypy":
                return False
        else:
            # Fallback: check sys.version string
            if "pypy" in getattr(sys, "version", "").lower():
                return False
    except Exception:
        # If any error occurs while checking PyPy, be conservative
        return False

    # 2. Check PURE_PYTHON environment variable
    try:
        pure_python = os.getenv("PURE_PYTHON")
        if pure_python is not None:
            # Normalize to lowercase for comparison
            val = pure_python.strip().lower()
            if val in ("1", "true", "yes", "on"):
                return False
    except Exception:
        # If environment lookup fails, ignore and proceed
        pass

    # Default: attempt C optimizations
    return True

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        return not _c_optimizations_required()
    except Exception:
        # If the required function is not defined or any error occurs, default to False
        return False

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        pure = globals()['PURE_PYTHON']
    except KeyError:
        # If the flag is not defined, assume C optimizations are needed.
        return True
    # Ensure the value is interpreted as a boolean.
    return not bool(pure)

