    try:
        points = getattr(self, "points", None)
        if points is None:
            # Fallback: try to iterate over self directly
            points = list(self)
    except Exception as exc:
        raise ValueError("Unable to access graph points") from exc

    # If no points, return header or empty string
    if not points:
        return "\n".join(lines)

    for point in points:
        # Each point is expected to be a tuple (coord, value)
        try:
            coord, value = point
        except Exception:
            # Skip malformed points
            continue

        # Build list of string parts
        parts = []

        # Handle coordinate (may be iterable)
        if hasattr(coord, "__iter__") and not isinstance(coord, (str, bytes)):
            parts.extend(str(c) for c in coord)
        else:
            parts.append(str(coord))

        # Handle value (may be iterable)
        if hasattr(value, "__iter__") and not isinstance(value, (str, bytes)):
            parts.extend(str(v) for v in value)
        else:
            parts.append(str(value))

        # Join parts with separator and add to lines
        lines.append(separator.join(parts))

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate the coordinate name
    if not isinstance(coord_name, str):
        raise TypeError(
            f"coord_name must be a string, got {type(coord_name).__name__}"
        )

    # Retrieve the error indices mapping
    err_map = getattr(self, "_err_indices", None)
    if err_map is None:
        raise AttributeError(
            "The object does not have an '_err_indices' attribute."
        )
    if not isinstance(err_map, dict):
        raise TypeError(
            f"_err_indices must be a dict, got {type(err_map).__name__}"
        )

    # Ensure the coordinate exists in the mapping
    if coord_name not in err_map:
        raise KeyError(
            f"Coordinate '{coord_name}' not found in error indices mapping."
        )

    indices = err_map[coord_name]

    # Handle None or scalar values gracefully
    if indices is None:
        return []

    # If indices is a scalar, wrap it in a list
    if isinstance(indices, (int, float, str, bytes)):
        return [indices]

    # Ensure the indices are iterable
    try:
        iter(indices)
    except TypeError:
        raise TypeError(
            f"Error indices for coordinate '{coord_name}' must be iterable, "
            f"got {type(indices).__name__}"
        )

    # Return a copy to avoid accidental mutation
    return list(indices)

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    if obj is None:
        return False
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    if obj is None:
        return False
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
    except Exception:
        return False

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        # Validate weight
        try:
            weight = float(weight)
        except Exception:
            raise TypeError("weight must be a numeric value")

        # Validate coord
        if coord is None:
            return
        try:
            coord_list = list(coord)
        except Exception:
            raise TypeError("coord must be an iterable of coordinates")

        if len(coord_list) != self.ndim:
            raise ValueError(f"coord must have {self.ndim} dimensions")

        # Find bin indices
        indices = []
        for dim, c in enumerate(coord_list):
            # Skip non-numeric or infinite values
            try:
                import math
                if not isinstance(c, (int, float)) or math.isnan(c) or math.isinf(c):
                    return
            except Exception:
                return

            edges = self._edges[dim]
            # Determine bin index using numpy if available, otherwise bisect
            try:
                import numpy as np
                idx = np.searchsorted(edges, c, side='right') - 1
            except Exception:
                import bisect
                idx = bisect.bisect_right(edges, c) - 1

            # Check bounds
            if idx < 0 or idx >= len(edges) - 1:
                return  # outside histogram bounds
            indices.append(idx)

        # Increment the appropriate bin
        idx_tuple = tuple(indices)
        try:
            self._data[idx_tuple] += weight
        except Exception:
            # If _data is a list of lists, try nested indexing
            try:
                sub = self._data
                for i in indices[:-1]:
                    sub = sub[i]
                sub[indices[-1]] += weight
            except Exception as e:
                raise ValueError(f"Failed to update histogram bin: {e}") from e

    except Exception as exc:
        raise ValueError(f"Failed to fill histogram: {exc}") from exc

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    # Ensure labels is a dictionary
    if not isinstance(labels, dict):
        raise ValidationError(messages=[{"labels": "labels must be a dict"}])

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            # Validate key regex
            if not re.match(LABEL_KEY_REGEX, key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex [...]"}
                )

        # Validate value(s)
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, (str, bytes)):
                    errors.append({f"['{v}']": "expected string or bytes-like object"})
                else:
                    if not re.match(LABEL_VALUE_REGEX, v):
                        errors.append(
                            {f"['{v}']": f"Label value '{v}' does not match the regex [...]"}
                        )
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): "expected string or bytes-like object"})
            else:
                if not re.match(LABEL_VALUE_REGEX, value):
                    errors.append(
                        {value: f"Label value '{value}' does not match the regex [...]"}
                    )

    if errors:
        raise ValidationError(messages=errors)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Basic validation
    if not isinstance(response, list):
        # Nothing to update if response is not a list
        return last_applied_manifest
    if not isinstance(observer_schema, list):
        # Without schema we cannot determine how to update
        return last_applied_manifest
    if last_applied_manifest is None:
        last_applied_manifest = []

    # Ensure we have a list to work with
    if not isinstance(last_applied_manifest, list):
        # If it's not a list, replace it with an empty list
        last_applied_manifest = []

    # Iterate over the response items
    for idx, resp_item in enumerate(response):
        # Ensure the last_applied_manifest list is long enough
        if idx >= len(last_applied_manifest):
            # Append a placeholder based on the type of resp_item
            if isinstance(resp_item, dict):
                last_applied_manifest.append({})
            elif isinstance(resp_item, list):
                last_applied_manifest.append([])
            else:
                last_applied_manifest.append(None)

        # Retrieve the corresponding schema element if available
        schema_item = observer_schema[idx] if idx < len(observer_schema) else None

        try:
            if isinstance(resp_item, dict):
                # If the schema item is a dict, we expect a dict update
                if isinstance(schema_item, dict):
                    # Delegate to the dict updater
                    last_applied_manifest[idx] = update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[idx], schema_item, resp_item
                    )
                else:
                    # No schema guidance; just copy the dict
                    last_applied_manifest[idx] = resp_item
            elif isinstance(resp_item, list):
                # Recursively update nested lists
                if isinstance(schema_item, list):
                    last_applied_manifest[idx] = update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[idx], schema_item, resp_item
                    )
                else:
                    # No schema guidance; just copy the list
                    last_applied_manifest[idx] = resp_item
            else:
                # Primitive value; set directly if not already set
                if last_applied_manifest[idx] is None:
                    last_applied_manifest[idx] = resp_item
        except Exception:
            # In case of any unexpected error, keep the original value
            pass

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate input
    if app is None:
        raise ValueError("app must not be None")

    # Retrieve manifest list
    try:
        manifest = getattr(app, "spec", None)
        if manifest is None:
            raise AttributeError
        manifest = getattr(manifest, "manifest", None)
    except AttributeError:
        raise ValueError("app.spec.manifest is required")

    if manifest is None:
        manifest = []

    if not isinstance(manifest, list):
        raise ValueError("app.spec.manifest must be a list")

    # Retrieve existing observer schema mapping
    try:
        existing_schema = getattr(app, "spec", None)
        if existing_schema is None:
            raise AttributeError
        existing_schema = getattr(existing_schema, "observer_schema", None)
    except AttributeError:
        existing_schema = None

    if existing_schema is None:
        existing_schema = {}
    if not isinstance(existing_schema, dict):
        raise ValueError("app.spec.observer_schema must be a dict if present")

    # Prepare default schema dictionary
    default_schema = {}

    for resource in manifest:
        # Skip non-dict-like resources
        if not isinstance(resource, (dict,)):
            continue

        # Try to get the kind of the resource
        kind = None
        try:
            kind = resource.get("kind") if isinstance(resource, dict) else getattr(resource, "kind", None)
        except Exception:
            continue

        if not isinstance(kind, str) or not kind:
            continue

        # Skip if a custom schema already exists for this kind
        if kind in existing_schema:
            continue

        # Skip if we already generated a default schema for this kind
        if kind in default_schema:
            continue

        # Build a simple default JSON schema for the resource
        schema = {
            "type": "object",
            "properties": {
                "metadata": {
                    "type": "object",
                    "properties": {
                        "name": {"type": "string"},
                        "namespace": {"type": "string"},
                    },
                    "required": ["name"],
                },
                "spec": {"type": "object"},
                "status": {"type": "object"},
            },
            "required": ["metadata"],
        }

        default_schema[kind] = schema

    return default_schema

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Validate prefix
    if prefix is None:
        prefix = ''
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")
    # Ensure the object has a status attribute
    if not hasattr(self, 'status'):
        raise AttributeError("The object does not have a 'status' attribute")
    # Convert status to string safely
    try:
        status_repr = str(self.status)
    except Exception as exc:
        raise RuntimeError(f"Failed to convert status to string: {exc}") from exc
    # Return concatenated result
    return f"{prefix}{status_repr}"

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic type check
        if not isinstance(inventory, dict):
            return False

        # Determine spec version if requested
        spec_version = getattr(self, "spec_version", None)
        if extract_spec_version:
            type_val = inventory.get("type")
            if isinstance(type_val, str):
                # Attempt to extract a version number from the type string
                # e.g., "spec-v1.2" -> "1.2"
                parts = type_val.split("-")
                if len(parts) >= 2:
                    ver_part = parts[-1]
                    if ver_part.lower().startswith("v"):
                        ver_candidate = ver_part[1:]
                        # Basic numeric check
                        try:
                            float(ver_candidate)
                            spec_version = ver_candidate
                        except ValueError:
                            pass
            # If extraction failed, keep the default spec_version

        # Simple validation rules
        # Inventory must have a name
        name = inventory.get("name")
        if not isinstance(name, str) or not name.strip():
            return False

        # Inventory must have items list
        items = inventory.get("items")
        if not isinstance(items, list):
            return False

        # Each item must be a dict with required keys
        for idx, item in enumerate(items):
            if not isinstance(item, dict):
                return False
            if "id" not in item or "quantity" not in item:
                return False
            if not isinstance(item["id"], (str, int)):
                return False
            if not isinstance(item["quantity"], int) or item["quantity"] < 0:
                return False

        # Optional: check spec_version format if present
        if spec_version is not None:
            try:
                float(spec_version)
            except (TypeError, ValueError):
                return False

        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate inputs
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping file names to digests")
    if digests_used is None:
        raise TypeError("digests_used cannot be None")
    try:
        digests_used_set = set(digests_used)
    except TypeError as exc:
        raise TypeError("digests_used must be an iterable of digests") from exc

    # Extract digests from the manifest
    manifest_digests = set(manifest_files.values())

    # Find any digests that are used but not present in the manifest
    missing = digests_used_set - manifest_digests
    if missing:
        raise ValueError(f"Digests used but not present in manifest: {missing}")

    # All required digests are present and used
    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic sanity checks
    if prior is None:
        raise ValueError("prior cannot be None")

    if not isinstance(prior, type(self)):
        raise ValueError(
            f"prior must be an instance of {type(self).__name__}, "
            f"got {type(prior).__name__}"
        )

    # Retrieve required attributes, raising a clear error if missing
    try:
        self_version = getattr(self, "version")
        prior_version = getattr(prior, "version")
        self_id = getattr(self, "inventory_id")
        prior_id = getattr(prior, "inventory_id")
    except AttributeError as exc:
        raise ValueError(f"Missing required attribute: {exc}") from exc

    # Version ordering: prior must be strictly older
    if prior_version >= self_version:
        raise ValueError(
            f"prior version {prior_version} must be less than current version {self_version}"
        )

    # Inventory identity must match
    if prior_id != self_id:
        raise ValueError(
            f"prior inventory_id {prior_id} does not match current inventory_id {self_id}"
        )

    # Optional: ensure prior data is a subset of current data if both have a 'data' attribute
    if hasattr(self, "data") and hasattr(prior, "data"):
        self_data = getattr(self, "data")
        prior_data = getattr(prior, "data")
        if isinstance(self_data, dict) and isinstance(prior_data, dict):
            for key, val in prior_data.items():
                if key not in self_data or self_data[key] != val:
                    raise ValueError(
                        f"prior data mismatch for key '{key}': "
                        f"expected {val}, found {self_data.get(key)}"
                    )
        else:
            # If data is not a dict, we skip subset validation
            pass

    # If all checks pass, return True
    return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inventory type
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or list of dicts")

    # Helper to extract mapping for a given version
    def _extract_mapping(inv, ver):
        if isinstance(inv, dict):
            # Direct mapping: version -> {logical_path: [files]}
            if ver in inv:
                mapping = inv[ver]
                if not isinstance(mapping, dict):
                    raise TypeError(f"Mapping for version {ver} must be a dict")
                return mapping
            # Alternative structure: 'versions' key
            if 'versions' in inv and isinstance(inv['versions'], list):
                for v in inv['versions']:
                    if isinstance(v, dict) and v.get('version') == ver:
                        mapping = v.get('files')
                        if mapping is None:
                            raise KeyError(f"No 'files' key for version {ver}")
                        if not isinstance(mapping, dict):
                            raise TypeError(f"'files' for version {ver} must be a dict")
                        return mapping
        elif isinstance(inv, list):
            # List of version dicts
            for v in inv:
                if isinstance(v, dict) and v.get('version') == ver:
                    mapping = v.get('files')
                    if mapping is None:
                        raise KeyError(f"No 'files' key for version {ver}")
                    if not isinstance(mapping, dict):
                        raise TypeError(f"'files' for version {ver} must be a dict")
                    return mapping
        raise KeyError(f"Version {ver} not found in inventory")

    try:
        raw_mapping = _extract_mapping(inventory, version)
    except Exception as exc:
        raise ValueError(f"Failed to retrieve mapping for version {version}: {exc}") from exc

    # Convert to desired output: logical_path -> set(content_files)
    result = {}
    for logical_path, files in raw_mapping.items():
        if not isinstance(files, (list, set, tuple)):
            raise TypeError(f"Files for logical path '{logical_path}' must be a list, set, or tuple")
        result[logical_path] = set(files)

    return result

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary.")
    if manifest_files is None:
        raise ValueError("manifest_files cannot be None.")
    if not hasattr(manifest_files, "__iter__"):
        raise ValueError("manifest_files must be an iterable of file paths.")

    # Normalize manifest file paths to a set of strings
    try:
        manifest_set = {str(p) for p in manifest_files}
    except Exception as exc:
        raise ValueError("manifest_files must contain string-like paths.") from exc

    # Get the list of files from the fixity block
    files = fixity.get("files")
    if files is None:
        # No files key is considered valid (empty fixity)
        return True
    if not isinstance(files, list):
        raise ValueError("The 'files' key in fixity must be a list.")

    seen_paths = set()
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"Fixity file entry at index {idx} must be a dictionary.")
        path = entry.get("path")
        if path is None:
            raise ValueError(f"Fixity file entry at index {idx} is missing the 'path' key.")
        if not isinstance(path, str):
            raise ValueError(f"Fixity file entry at index {idx} has a non-string 'path'.")
        if path in seen_paths:
            raise ValueError(f"Duplicate path '{path}' found in fixity block.")
        seen_paths.add(path)

        # Ensure the path is present in the manifest
        if path not in manifest_set:
            raise ValueError(f"Fixity references unknown file '{path}' not present in the manifest.")

        # Optional: validate hash and size fields
        h = entry.get("hash")
        if h is None:
            raise ValueError(f"Fixity file entry for '{path}' is missing the 'hash' key.")
        if not isinstance(h, str) or not h:
            raise ValueError(f"Fixity file entry for '{path}' has an invalid 'hash' value.")

        size = entry.get("size")
        if size is None:
            raise ValueError(f"Fixity file entry for '{path}' is missing the 'size' key.")
        if not isinstance(size, int) or size < 0:
            raise ValueError(f"Fixity file entry for '{path}' has an invalid 'size' value.")

    return True

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    try:
        return content.replace('w:st="', 'w-st="')
    except Exception as e:
        raise RuntimeError(f"Error processing content: {e}") from e

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None:
        return None
    if not pubdate_xpaths:
        return None

    # Ensure we have an iterable of xpaths
    if isinstance(pubdate_xpaths, str):
        xpaths = [pubdate_xpaths]
    else:
        try:
            iter(pubdate_xpaths)
            xpaths = list(pubdate_xpaths)
        except TypeError:
            # Not iterable, treat as single xpath
            xpaths = [pubdate_xpaths]

    for xpath in xpaths:
        try:
            result = node.xpath(xpath)
            if result:
                first = result[0]
                # If it's a string, return it directly
                if isinstance(first, str):
                    return first.strip()
                # If it's an element, return its text content if available
                if hasattr(first, 'text') and first.text is not None:
                    return first.text.strip()
                # Fallback: convert to string
                return str(first).strip()
        except Exception:
            # Ignore errors from invalid xpath or evaluation issues
            continue

    # No match found
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate parameters
    if not isinstance(indent, int) or indent < 0:
        raise TypeError("indent must be a non-negative integer")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")

    visited = set()

    def _type_repr(obj):
        """Return a string representation of the object's type."""
        return f" ({type(obj).__name__})"

    def _pretty_obj(obj, level):
        """Recursively build a pretty string for obj."""
        # Handle circular references
        obj_id = id(obj)
        if obj_id in visited:
            return "<Circular Reference>"
        visited.add(obj_id)

        prefix = " " * (indent * level)

        # Primitive types
        if isinstance(obj, (int, float, complex, bool, str, bytes, type(None))):
            return repr(obj) + (_type_repr(obj) if debug else "")

        # Dictionaries
        if isinstance(obj, dict):
            if not obj:
                return "{}"
            items = []
            for k, v in obj.items():
                key_repr = repr(k)
                val_repr = _pretty_obj(v, level + 1)
                if debug:
                    val_repr += _type_repr(v)
                items.append(f"{prefix}  {key_repr}: {val_repr}")
            return "{\n" + ",\n".join(items) + f"\n{prefix}}}"

        # Lists, tuples, sets, frozensets
        if isinstance(obj, (list, tuple, set, frozenset)):
            if isinstance(obj, list):
                opening, closing = "[", "]"
            elif isinstance(obj, tuple):
                opening, closing = "(", ")"
            elif isinstance(obj, set):
                opening, closing = "set([", "])"
            else:  # frozenset
                opening, closing = "frozenset([", "])"

            if not obj:
                return opening[0] + closing[0] if opening in ("[", "(", "set([", "frozenset([") else opening + closing

            items = []
            for item in obj:
                item_repr = _pretty_obj(item, level + 1)
                if debug:
                    item_repr += _type_repr(item)
                items.append(f"{prefix}  {item_repr}")
            return opening + "\n" + ",\n".join(items) + f"\n{prefix}{closing}"

        # Objects with __dict__ or __slots__
        if hasattr(obj, "__dict__") or hasattr(obj, "__slots__"):
            try:
                attrs = {}
                if hasattr(obj, "__dict__"):
                    attrs = vars(obj)
                else:
                    # Handle __slots__
                    for slot in getattr(obj, "__slots__", []):
                        try:
                            attrs[slot] = getattr(obj, slot)
                        except AttributeError:
                            pass
            except Exception:
                attrs = {}

            if not attrs:
                return f"{obj.__class__.__name__}()"

            items = []
            for k, v in attrs.items():
                val_repr = _pretty_obj(v, level + 1)
                if debug:
                    val_repr += _type_repr(v)
                items.append(f"{prefix}  {k} = {val_repr}")
            return f"{obj.__class__.__name__}(\n" + ",\n".join(items) + f

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings.
    """
    import sys

    def wrapper(*args, **kwargs):
        # Call the original function
        result = namefunc(*args, **kwargs)

        # If the result is None, just return it
        if result is None:
            return None

        # In Python 3, str is unicode; in Python 2, str is bytes
        # We want to return bytes in both cases
        if isinstance(result, bytes):
            # Already a bytestring
            return result

        # Handle Python 2 unicode objects
        if sys.version_info[0] < 3:
            # In Python 2, unicode type is 'unicode'
            try:
                unicode_type = unicode  # noqa: F821
            except NameError:
                unicode_type = str  # Fallback, should not happen
            if isinstance(result, unicode_type):
                try:
                    return result.encode('utf-8')
                except Exception:
                    # If encoding fails, return the original
                    return result
            # If it's a str (bytes) in Python 2, return as is
            if isinstance(result, str):
                return result
            # For any other type, return as is
            return result

        # Python 3 path: result is a str (unicode)
        if isinstance(result, str):
            try:
                return result.encode('utf-8')
            except Exception:
                return result

        # Fallback: return the result unchanged
        return result

    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to obtain the package name from the current module context
    pkg_name = __package__ or __name__.split('.')[0]
    # If the module is executed as a script, __package__ may be None and __name__ may be "__main__".
    # In that case, we cannot reliably determine the package name, so we fall back to a default.
    if pkg_name in (None, "__main__"):
        return "0.0.0"

    # Attempt to retrieve the version using importlib.metadata (Python 3.8+)
    try:
        from importlib.metadata import version, PackageNotFoundError
        return version(pkg_name)
    except Exception:
        # Fallback to pkg_resources for older Python versions or if importlib.metadata fails
        try:
            import pkg_resources
            return pkg_resources.get_distribution(pkg_name).version
        except Exception:
            # If all attempts fail, return a default version string
            return "0.0.0"

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        # If pieces contains a '+' character, return '.'
        if '+' in pieces:
            return '.'
        # Otherwise, return '+'
        return '+'
    except TypeError as exc:
        # pieces is not iterable or not a suitable type
        raise TypeError("pieces must be an iterable containing characters or strings") from exc

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        return {}

    # Ensure required attributes exist
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise AttributeError("self.root_inventory must be defined as a dict before validation")

    # Prepare storage for differences
    self.different_digests = {}

    # Import modules locally to avoid top-level imports
    import os
    import json

    for idx, dir_name in enumerate(version_dirs, start=1):
        # Build path to the inventory file
        inventory_path = os.path.join(dir_name, "inventory.json")
        if not os.path.isfile(inventory_path):
            raise FileNotFoundError(f"Missing inventory file in version directory '{dir_name}'")

        # Load the inventory
        try:
            with open(inventory_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory from '{inventory_path}': {exc}")

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory in '{inventory_path}' is not a dictionary")

        # Ensure the inventory contains all files from the root inventory
        missing_files = set(self.root_inventory.keys()) - set(inv.keys())
        if missing_files:
            raise ValueError(
                f"Inventory in '{inventory_path}' is missing files: {sorted(missing_files)}"
            )

        # Record any digest differences
        for file_path, root_digest in self.root_inventory.items():
            inv_digest = inv.get(file_path)
            if inv_digest != root_digest:
                self.different_digests.setdefault(file_path, []).append((idx, inv_digest))

    return self.different_digests

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        from pathlib import Path
    except Exception as exc:
        return f"failed to import Path: {exc}"

    # Ensure path is a Path object
    try:
        p = Path(path)
    except Exception as exc:
        return f"invalid path argument: {exc}"

    if not p.exists():
        return "path does not exist"

    if p.is_file():
        return "file"

    if p.is_dir():
        # Check for Namaste file "0=*"
        namaste = p / "0=*"
        if not namaste.is_file():
            return "no Namaste file found"
        # Determine if this is a root by presence of 'objects' subdirectory
        objects_dir = p / "objects"
        if objects_dir.is_dir():
            return "root"
        else:
            return "object"

    return "path is neither file nor directory"

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a mapping node (has a list of key/value tuples)
    def is_mapping_node(node):
        return hasattr(node, 'value') and isinstance(node.value, list) and all(
            isinstance(pair, tuple) and len(pair) == 2 for pair in node.value
        )

    # Merge two nodes: if both are mapping nodes, deep merge their contents; otherwise, return the second node
    def merge_nodes(a, b):
        if is_mapping_node(a) and is_mapping_node(b):
            merged_list = merge_mapping_lists(a.value, b.value)
            a.value = merged_list
            return a
        return b

    # Merge two lists of mapping entries (each entry is a (key_node, value_node) tuple)
    def merge_mapping_lists(list_a, list_b):
        # Use an ordered dict-like approach to preserve first appearance order
        seen = {}
        order = []

        def add_entry(key_node, val_node):
            key_str = getattr(key_node, 'value', None)
            if key_str is None:
                # If key_node doesn't have a 'value', use its id to avoid collisions
                key_str = id(key_node)
            if key_str not in seen:
                seen[key_str] = (key_node, val_node)
                order.append(key_str)
            else:
                # Merge existing value
                existing_key_node, existing_val_node = seen[key_str]
                merged_val = merge_nodes(existing_val_node, val_node)
                seen[key_str] = (existing_key_node, merged_val)

        for key_node, val_node in list_a:
            add_entry(key_node, val_node)
        for key_node, val_node in list_b:
            add_entry(key_node, val_node)

        # Build result list preserving order
        result = []
        for key_str in order:
            result.append(seen[key_str])
        return result

    # Validate input
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list')
    for idx, item in enumerate(nodes):
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError(f'Each element of nodes must be a tuple of length 2, got {item!r} at index {idx}')

    merged = {}
    order = []

    for key_node, val_node in nodes:
        key_str = getattr(key_node, 'value', None)
        if key_str is None:
            key_str = id(key_node)
        if key_str not in merged:
            merged[key_str] = (key_node, val_node)
            order.append(key_str)
        else

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping_node(node):
        try:
            return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'
        except Exception:
            return False

    # Merge two mapping nodes in place: node1 will be updated to contain merged data
    def merge_mapping_nodes(node1, node2):
        if not (is_mapping_node(node1) and is_mapping_node(node2)):
            return node2  # fallback: last wins
        # Build index of existing keys in node1
        key_to_index = {}
        for idx, (k, _) in enumerate(node1.value):
            key_to_index[k.value] = idx
        # Iterate over node2's mapping entries
        for k2, v2 in node2.value:
            if k2.value in key_to_index:
                idx = key_to_index[k2.value]
                _, v1 = node1.value[idx]
                # If both values are mapping nodes, merge recursively
                if is_mapping_node(v1) and is_mapping_node(v2):
                    merged = merge_mapping_nodes(v1, v2)
                    node1.value[idx] = (k2, merged)
                else:
                    # Non-mapping: last wins
                    node1.value[idx] = (k2, v2)
            else:
                # Append new key-value pair
                node1.value.append((k2, v2))
        return node1

    # Validate input
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list')
    result_dict = {}
    order = []
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError('each node must be a tuple of (ScalarNode, value)')
        key_node, value_node = item
        if not hasattr(key_node, 'value'):
            raise TypeError('key node must have a value attribute')
        key = key_node.value
        if key in result_dict:
            existing_key_node, existing_value_node = result_dict[key]
            # Merge values
            if is_mapping_node(existing_value_node) and is_mapping_node(value_node):
                merged = merge_mapping_nodes(existing_value_node, value_node)
                result_dict[key] = (existing_key_node, merged)
            else:
                # Non-mapping: last wins
                result_dict[key] = (existing_key_node, value_node)
        else:
            result_dict[key] = (key_node, value_node)
            order.append(key)
    # Build ordered list of tuples
    merged_list = [(result_dict[k][0], result_dict[k][1]) for k in order]
    return merged_list

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Input must be an iterable of dictionaries, got None")
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError(f"Input must be an iterable of dictionaries, got {type(dicts).__name__}")

    result = {}
    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise TypeError(f"Element at index {idx} is not a dict, got {type(d).__name__}")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for key '{key}' in dict at index {idx} is not numeric, got {type(value).__name__}")
            result[key] = result.get(key, 0) + value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if url_args is None:
        url_args = {}
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dictionary")
    result = url
    start = 0
    while True:
        open_brace = result.find('{', start)
        if open_brace == -1:
            break
        close_brace = result.find('}', open_brace + 1)
        if close_brace == -1:
            break
        key = result[open_brace + 1:close_brace]
        if key in url_args:
            val = url_args[key]
            val = '' if val is None else str(val)
            result = result[:open_brace] + val + result[close_brace + 1:]
            start = open_brace + len(val)
        else:
            start = close_brace + 1
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Only strings can represent a None value in textual form.
    if not isinstance(val, str):
        return False
    # Normalize the string: strip whitespace and convert to lowercase.
    normalized = val.strip().lower()
    # Common textual representations of None.
    return normalized in {"none", "null", "nil"}

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    if parser is None:
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    if not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    try:
        for action in parser._actions:
            option_strings = getattr(action, "option_strings", None)
            if option_strings:
                flags.extend(option_strings)
    except Exception as exc:
        raise ValueError(f"Failed to extract flags: {exc}") from exc
    return " ".join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")
    if not alphabet:
        raise ValueError("alphabet must contain at least one symbol")
    if not all(isinstance(sym, str) for sym in alphabet):
        raise TypeError("all elements of alphabet must be strings")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two distinct symbols for base conversion")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)
    digits: List[str] = []

    # Special case for zero
    if number == 0:
        digits.append(alphabet[0])
    else:
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])

    # The digits are collected least significant first; reverse them
    digits.reverse()
    result = ''.join(digits)

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        pad_len = padding - len(result)
        result = alphabet[0] * pad_len + result

    return result

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Validate inputs
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_value, (str, int, float, tuple)):
        raise TypeError("register_value must be a hashable type")
    # Helper to recursively replace keys
    def _replace_in_dict(d):
        keys_to_process = list(d.keys())
        for key in keys_to_process:
            # Replace key if it matches register_value
            if key == register_value:
                d[register_number] = d.pop(key)
            # Recurse into nested dicts
            val = d[key]
            if isinstance(val, dict):
                _replace_in_dict(val)
            elif isinstance(val, list):
                for item in val:
                    if isinstance(item, dict):
                        _replace_in_dict(item)
    try:
        _replace_in_dict(flow_params)
    except Exception as e:
        raise RuntimeError(f"Error while replacing register: {e}") from e
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type")
    result = set()
    try:
        direct_subs = cls.__subclasses__()
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve subclasses of {cls}") from exc
    for sub in direct_subs:
        result.add(sub)
        result.update(subclasses(sub))
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate alphabet
    if not alphabet:
        raise ValueError("Alphabet must contain at least one character.")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet characters must be unique.")
    base = len(alphabet)

    # Build mapping from character to its numeric value
    char_to_value = {ch: idx for idx, ch in enumerate(alphabet)}

    # Handle empty string: interpret as zero
    if string == "":
        return 0

    result = 0
    for idx, ch in enumerate(string):
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' at position {idx} not found in alphabet.")
        result = result * base + char_to_value[ch]
    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True if macOS
    :rtype: bool
    """
    try:
        # os.uname() is available on Unix-like systems, including macOS
        return os.uname().sysname == "Darwin"
    except AttributeError:
        # os.uname() not available (e.g., on Windows). Fall back to platform module.
        try:
            import platform
            return platform.system() == "Darwin"
        except Exception:
            # If any unexpected error occurs, conservatively return False
            return False
    except Exception:
        # Any other unexpected error should also result in False
        return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError(f"Expected a string, got {type(name).__name__}")
    # Remove leading or trailing single or double quotes
    return re.sub(r"^['\"]|['\"]$", "", name)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Validate input type
    if not isinstance(s, str):
        raise TypeError(f"split() argument must be a string, got {type(s).__name__}")

    # Determine POSIX flag based on platform argument
    if platform == 'this':
        try:
            import sys
            posix = not sys.platform.startswith('win')
        except Exception:
            posix = True  # default to POSIX if detection fails
    elif platform == 1:
        posix = True
    elif platform == 0:
        posix = False
    else:
        raise ValueError(f"Unsupported platform value: {platform}")

    # Use shlex for robust parsing; it handles quoting and escaping
    try:
        import shlex
        return shlex.split(s, posix=posix)
    except Exception as exc:
        # Wrap any parsing errors in a ValueError for consistency
        raise ValueError(f"Error parsing command line: {exc}") from exc

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Import required modules locally to avoid global imports
    from pathlib import Path
    import shutil
    import uuid
    import os
    import tempfile

    # Resolve paths
    archive = Path(archive_path).expanduser().resolve()
    if not archive.is_file():
        raise FileNotFoundError(f"Archive file does not exist: {archive}")

    tmp_dir = Path(tmp_path).expanduser().resolve()
    try:
        tmp_dir.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise RuntimeError(f"Could not create temporary directory '{tmp_dir}': {exc}") from exc

    # Create a unique extraction directory inside tmp_dir
    extract_dir = tmp_dir / f"repo_extract_{uuid.uuid4().hex}"
    try:
        extract_dir.mkdir()
    except Exception as exc:
        raise RuntimeError(f"Could not create extraction directory '{extract_dir}': {exc}") from exc

    # Unpack the archive
    try:
        shutil.unpack_archive(str(archive), str(extract_dir))
    except Exception as exc:
        # Clean up partially extracted files
        try:
            shutil.rmtree(extract_dir)
        except Exception:
            pass
        raise RuntimeError(f"Failed to unpack archive '{archive}': {exc}") from exc

    # Determine the repository root directory
    # If a filename is provided, create a subdirectory with that name and move all extracted content into it
    if filename:
        repo_dir = extract_dir / filename
        try:
            repo_dir.mkdir()
        except Exception as exc:
            raise RuntimeError(f"Could not create repository directory '{repo_dir}': {exc}") from exc
        # Move all extracted items into the new directory
        for item in extract_dir.iterdir():
            if item == repo_dir:
                continue
            try:
                shutil.move(str(item), str(repo_dir))
            except Exception as exc:
                raise RuntimeError(f"Failed to move '{item}' to '{repo_dir}': {exc}") from exc
    else:
        # If only one top-level directory exists, use it as the repo root
        top_level = [p for p in extract_dir.iterdir() if p.is_dir()]
        if len(top_level) == 1:
            repo_dir = top_level[0]
        else:
            # Otherwise, use the extraction directory itself
            repo_dir = extract_dir

    # Return a file URL that can be used as a git remote
    repo_url = f"file://{repo_dir.resolve()}"
    return repo_url

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str) or not host.strip():
        return False
    host = host.strip()
    try:
        # Resolve the host to all possible addresses
        addrinfo = socket.getaddrinfo(host, None)
    except Exception:
        return False

    for family, _, _, _, sockaddr in addrinfo:
        # sockaddr is a tuple; the first element is the IP address string
        ip = sockaddr[0]
        if family == socket.AF_INET:
            # IPv4 loopback addresses start with 127.
            if ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            # IPv6 loopback address is ::1
            if ip == "::1":
                return True
    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    """
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise TypeError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Resolve absolute path
    config_path = os.path.abspath(config_filename)

    # Check if file exists
    if os.path.exists(config_path):
        if not overwrite:
            raise FileExistsError(f"File '{config_path}' already exists and overwrite is False")
        if os.path.isdir(config_path):
            raise IsADirectoryError(f"Path '{config_path}' is a directory")

    # Ensure parent directory exists
    parent_dir = os.path.dirname(config_path)
    if parent_dir and not os.path.isdir(parent_dir):
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except OSError as exc:
            raise RuntimeError(f"Failed to create directories '{parent_dir}': {exc}") from exc

    # Write the file
    try:
        with open(config_path, "w", encoding="utf-8") as f:
            f.write(rendered_config)
        # Set file permissions
        try:
            os.chmod(config_path, mode)
        except OSError as exc:
            # If chmod fails, we still consider the write successful but warn
            raise RuntimeError(f"Failed to set permissions on '{config_path}': {exc}") from exc
    except OSError as exc:
        raise RuntimeError(f"Failed to write configuration to '{config_path}': {exc}") from exc
    return None

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Accept a plain string as a matcher (just the variable name)
    if isinstance(matcher, str):
        name = matcher
        default = None
    else:
        # Expect a tuple or list with 1 or 2 elements
        if not isinstance(matcher, (tuple, list)):
            raise TypeError("matcher must be a string, tuple, or list")
        if not (1 <= len(matcher) <= 2):
            raise ValueError("matcher must contain a name and an optional default value")
        name = matcher[0]
        if not isinstance(name, str):
            raise TypeError("environment variable name must be a string")
        default = matcher[1] if len(matcher) == 2 else None

    # Retrieve the environment variable
    value = os.getenv(name)

    if value is None:
        if default is not None:
            return str(default)
        else:
            raise KeyError(f"Environment variable '{name}' not found and no default provided")

    return value

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        addr = ipaddress.ip_address(target)
        return isinstance(addr, ipaddress.IPv4Address)
    except Exception:
        return False

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    if not isinstance(shape, tuple):
        raise TypeError("shape must be a tuple of integers")
    for dim in shape:
        if not isinstance(dim, int):
            raise TypeError(f"shape dimension {dim!r} is not an integer")
        if dim < 0:
            raise ValueError(f"shape dimension {dim!r} is negative")

    # Validate dtype
    try:
        dtype = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype: {dtype!r}") from exc

    # Create the array
    try:
        return np.empty(shape, dtype=dtype)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array with shape {shape!r} and dtype {dtype}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    # Validate input
    if x is None:
        raise ValueError("Input cannot be None.")
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError("Input must be a numeric type or array-like of numeric types.") from e
    # Compute Gaussian
    mu = 0.2
    sigma = 0.1
    return np.exp(-((arr - mu) ** 2) / (2 * sigma ** 2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, re, logging
    configs = {}
    errors = []

    # Helper to create a LogRecord for an error
    def _log_error(msg, exc_info=None):
        record = logging.LogRecord(
            name='load_configurations',
            level=logging.ERROR,
            pathname='',
            lineno=0,
            msg=msg,
            args=(),
            exc_info=exc_info
        )
        return record

    # Regex to find ${VAR} patterns
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def _resolve_env_in_value(value):
        if isinstance(value, str):
            def repl(match):
                var = match.group(1)
                return os.getenv(var, match.group(0))
            return env_pattern.sub(repl, value)
        return value

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError as e:
                    errors.append(_log_error(f'JSON decode error in {filename}: {e}', exc_info=True))
                    continue
        except (FileNotFoundError, PermissionError) as e:
            errors.append(_log_error(f'File error for {filename}: {e}', exc_info=True))
            continue
        except Exception as e:
            errors.append(_log_error(f'Unexpected error reading {filename}: {e}', exc_info=True))
            continue

        # Basic validation: config must be a dict
        if not isinstance(data, dict):
            errors.append(_log_error(f'Configuration in {filename} is not a JSON object', exc_info=True))
            continue

        # Resolve environment variables if requested
        if resolve_env:
            def _resolve_dict(d):
                for k, v in d.items():
                    if isinstance(v, dict):
                        _resolve_dict(v)
                    else:
                        d[k] = _resolve_env_in_value(v)
            _resolve_dict(data)

        # Apply overrides if provided
        if overrides:
            if not isinstance(overrides, dict):
                errors.append(_log_error(f'Overrides for {filename} is not a dict', exc_info=True))
            else:
                # shallow merge: overrides replace existing keys
                data.update(overrides)

        configs[filename] = data

    return configs, errors

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        try:
            return obj.encode("utf-8")
        except Exception as exc:
            raise ValueError(f"Unable to encode string to UTF-8: {exc}") from exc
    return obj

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Retrieve the registry of handlers; default to empty dict if not defined
    handlers = getattr(cls, "_protocol_handlers", {})
    if not isinstance(handlers, dict):
        raise TypeError("Protocol handlers registry must be a dictionary")

    # If a specific protocol version is requested
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        # Return a dict with the handler if supported, otherwise empty
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}

    # No specific version requested; return a copy of all handlers
    return dict(handlers)

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    else:
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Attempt to use an OrderedDict-like structure that supports popitem(last=False)
    data = None
    if hasattr(self, "_data"):
        data = self._data
    elif hasattr(self, "cache"):
        data = self.cache
    else:
        raise AttributeError("The object does not have a suitable data structure for popitem.")

    try:
        # popitem(last=False) removes the first (least recently used) item
        return data.popitem(last=False)
    except KeyError:
        # The underlying structure is empty
        raise KeyError("popitem(): dictionary is empty")
    except Exception as exc:
        # Re‑raise any unexpected exception with a clear message
        raise RuntimeError(f"Unexpected error during popitem: {exc}") from exc

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Try to use the built‑in OrderedDict implementation if available
    try:
        return super().popitem(last=True)
    except AttributeError:
        # Fallback for custom LRU implementations
        # Common patterns: a dict named `_data`/`cache` and an order list/deque named `_order`/`order`
        data_attr = None
        order_attr = None
        if hasattr(self, "_data") and hasattr(self, "_order"):
            data_attr, order_attr = "_data", "_order"
        elif hasattr(self, "cache") and hasattr(self, "order"):
            data_attr, order_attr = "cache", "order"
        else:
            raise NotImplementedError("popitem not supported for this class")

        data = getattr(self, data_attr)
        order = getattr(self, order_attr)

        if not order:
            raise KeyError("popitem(): dictionary is empty")

        key = order.pop()
        try:
            value = data.pop(key)
        except KeyError:
            # Inconsistent state: key missing from data
            raise KeyError(f"Key {key!r} not found in data during popitem") from None
        return key, value

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        # Attempt to determine a style from the instance, if any
        style = getattr(self, "paramstyle", None) or getattr(self, "style", None)
        if style is not None:
            try:
                # Try to instantiate with the style if the constructor accepts it
                return _converting._Converter(style)
            except TypeError:
                # Fallback to the default constructor if style is not accepted
                return _converting._Converter()
        # Default constructor if no style is specified
        return _converting._Converter()
    except Exception as exc:
        # Wrap any exception in a RuntimeError to provide a clear message
        raise RuntimeError("Unable to create parameter style converter") from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if request is None:
        return False
    try:
        # Handle dictionary-like requests
        if isinstance(request, dict):
            if request.get("public_message"):
                return True
            if request.get("private_message"):
                return True
            if request.get("legacy_payload"):
                return True
        else:
            # Handle object-like requests
            if getattr(request, "public_message", None):
                return True
            if getattr(request, "private_message", None):
                return True
            if getattr(request, "legacy_payload", None):
                return True
    except Exception:
        # Any unexpected error is treated as not a Diaspora request
        return False
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Handle dictionary-like request objects
        if isinstance(request, dict):
            path = request.get("path") or request.get("url")
            headers = request.get("headers", {})
        else:
            # Handle object with attributes
            path = getattr(request, "path", None) or getattr(request, "url", None)
            headers = getattr(request, "headers", {})
        # Check for typical Matrix path prefix
        if isinstance(path, str) and path.startswith("/_matrix"):
            return True
        # Check headers for Matrix-specific markers
        if isinstance(headers, dict):
            for key, value in headers.items():
                if not isinstance(key, str) or not isinstance(value, str):
                    continue
                key_lower = key.lower()
                if key_lower == "x-matrix-request":
                    return True
                if key_lower == "content-type" and "application/json" in value.lower():
                    return True
        return False
    except Exception:
        # Any unexpected error results in a conservative False
        return False

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        tag = tag.strip()
        if not tag:
            return False
        # Optional length limit (common in tag systems)
        if len(tag) > 30:
            return False
        import re
        # Tags must be lowercase alphanumerics separated by single hyphens
        pattern = re.compile(r'^[a-z0-9]+(?:-[a-z0-9]+)*$')
        return bool(pattern.match(tag))
    except Exception:
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Handle None or non‑Element inputs gracefully
    if node is None or not hasattr(node, "tag"):
        return {}

    try:
        children = list(node)
    except Exception:
        # If node is not iterable, return an empty dict
        return {}

    result = {}
    for child in children:
        # Only include elements that have a tag attribute
        if hasattr(child, "tag"):
            result[child.tag] = child
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Input must be a non-empty string")

    import json
    import xml.etree.ElementTree as ET

    doc = document.strip()
    result: Dict = {}

    # Try JSON first
    if doc[0] in ('{', '['):
        try:
            data = json.loads(doc)
        except json.JSONDecodeError as exc:
            raise ValueError(f"Invalid JSON webfinger document: {exc}") from exc

        if not isinstance(data, dict):
            raise ValueError("JSON webfinger document must be an object")

        # Extract fields
        result['subject'] = data.get('subject')
        result['aliases'] = data.get('aliases', [])
        result['links'] = data.get('links', [])
        return result

    # Otherwise, try XRD (XML)
    try:
        root = ET.fromstring(doc)
    except ET.ParseError as exc:
        raise ValueError(f"Invalid XML webfinger document: {exc}") from exc

    # Helper to strip namespace
    def _strip_ns(tag: str) -> str:
        return tag.split('}', 1)[-1] if '}' in tag else tag

    subject = None
    aliases = []
    links = []

    for child in root.iter():
        tag = _strip_ns(child.tag)
        if tag == 'Subject' and subject is None:
            subject = child.text
        elif tag == 'Alias':
            if child.text:
                aliases.append(child.text)
        elif tag == 'Link':
            link_attrs = {}
            for attr_name, attr_value in child.attrib.items():
                link_attrs[attr_name] = attr_value
            # Also capture any child elements inside Link if needed
            # For simplicity, we ignore nested elements
            links.append(link_attrs)

    if subject is None:
        raise ValueError("XRD webfinger document missing <Subject> element")

    result['subject'] = subject
    result['aliases'] = aliases
    result['links'] = links
    return result

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file names from the provided settings_dirs that match the spec_option.
    If settings_dirs is not a list or is None, an empty list is returned.
    If spec_option is None or empty, all file names from settings_dirs are returned.
    The function does not perform any filesystem operations; it simply filters the
    provided list of names.
    """
    # Validate settings_dirs
    if not isinstance(settings_dirs, (list, tuple)):
        return []

    # If spec_option is falsy, return all names
    if not spec_option:
        return list(settings_dirs)

    # Filter names that contain the spec_option substring
    filtered = []
    for name in settings_dirs:
        try:
            if spec_option in name:
                filtered.append(name)
        except Exception:
            # Skip any non-string entries
            continue
    return filtered

