@classmethod
def validate_from_content(cls, spec_content=None):
    """
    Validates that spec (YAML) content has all required fields.

    :param spec_content: content of spec file (string, bytes, or dict)
    :raise IRValidatorException: when mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    # Helper exception class is assumed to be defined elsewhere
    try:
        from typing import Any
    except Exception:
        pass  # typing is optional for type hints

    # Define required fields (adjust as needed for your spec)
    required_fields = ["name", "version", "description"]

    # Handle None input
    if spec_content is None:
        raise IRValidatorException("Spec content is None")

    # Convert bytes to string if necessary
    if isinstance(spec_content, (bytes, bytearray)):
        try:
            spec_content = spec_content.decode("utf-8")
        except Exception as e:
            raise IRValidatorException(f"Failed to decode spec content: {e}")

    # Load YAML if content is a string
    if isinstance(spec_content, str):
        try:
            import yaml
            data = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f"Failed to parse YAML: {e}")
    elif isinstance(spec_content, dict):
        data = spec_content
    else:
        raise IRValidatorException(
            f"Unsupported spec_content type: {type(spec_content).__name__}"
        )

    # Ensure the parsed data is a dictionary
    if not isinstance(data, dict):
        raise IRValidatorException(
            f"Spec content must be a mapping, got {type(data).__name__}"
        )

    # Check for missing required fields
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(
            f"Missing required fields in spec: {', '.join(missing)}"
        )

    return data

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    # Basic validation of the input
    if yaml_file is None:
        raise IRValidatorException("No YAML file path provided.")
    # Accept pathlib.Path or string
    try:
        path = str(yaml_file)
    except Exception as exc:
        raise IRValidatorException(f"Invalid yaml_file path: {yaml_file}") from exc

    # Attempt to read and parse the YAML file
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = yaml.safe_load(fh)
    except FileNotFoundError as exc:
        raise IRValidatorException(f"YAML file not found: {path}") from exc
    except yaml.YAMLError as exc:
        raise IRValidatorException(f"Error parsing YAML file: {path}") from exc
    except Exception as exc:
        raise IRValidatorException(f"Unexpected error reading YAML file: {path}") from exc

    # Ensure the root of the YAML is a dictionary
    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a dictionary at the root.")

    # Validate required fields if defined
    required_fields = getattr(cls, "REQUIRED_FIELDS", None)
    if required_fields:
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(
                f"Missing required fields in YAML file: {', '.join(missing)}"
            )

    return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    try:
        spec = getattr(self, "spec", None)
        if not isinstance(spec, dict):
            raise TypeError("spec must be a dictionary")
        defaults = {}
        for key, value in spec.items():
            # If the spec entry is a dict, look for 'default' or 'default_factory'
            if isinstance(value, dict):
                if "default" in value:
                    default_val = value["default"]
                elif "default_factory" in value:
                    factory = value["default_factory"]
                    if not callable(factory):
                        raise TypeError(f"default_factory for '{key}' is not callable")
                    try:
                        default_val = factory()
                    except Exception as exc:
                        raise ValueError(f"Error calling default_factory for '{key}': {exc}") from exc
                else:
                    # No default specified; skip this key
                    continue
            else:
                # Direct default value
                default_val = value
            defaults[key] = default_val
        return defaults
    except Exception as exc:
        raise RuntimeError(f"Failed to resolve spec defaults: {exc}") from exc

def get_deprecated_args(self):
    """Return a dict mapping options that deprecate others to the list of deprecated options."""
    try:
        mapping = getattr(self, 'deprecated_args', {})
        if not isinstance(mapping, dict):
            return {}
        result = {}
        for key, value in mapping.items():
            if isinstance(value, (list, tuple)):
                result[key] = list(value)
            else:
                result[key] = [value]
        return result
    except Exception:
        return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Validate input types
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve deprecated arguments mapping if defined on the instance.
    # The mapping should be a dict where keys are deprecated argument names
    # and values are the replacement argument names (or None if no replacement).
    deprecated_map = getattr(self, "deprecated_args", {})
    if not isinstance(deprecated_map, dict):
        # If the attribute exists but is not a dict, ignore it.
        deprecated_map = {}

    # Helper to process a single argument dictionary
    def _process_args(arg_dict, source_name):
        for key in arg_dict:
            # Skip non-string keys or None values
            if not isinstance(key, str) or key is None:
                continue
            if key in deprecated_map:
                replacement = deprecated_map[key]
                try:
                    if replacement:
                        print(f"Warning: Argument '{key}' from {source_name} is deprecated. "
                              f"Use '{replacement}' instead.")
                    else:
                        print(f"Warning: Argument '{key}' from {source_name} is deprecated and "
                              f"has no replacement.")
                except Exception:
                    # If printing fails, silently ignore to avoid breaking the flow
                    pass

    # Process CLI arguments
    _process_args(cli_args, "CLI")
    # Process answer file arguments
    _process_args(answer_file_args, "answer file")
    # No explicit return value needed.

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")
    if not isinstance(argument_name, str):
        raise TypeError(f"argument_name must be a string, got {type(argument_name).__name__}")

    # Ensure the commands mapping exists
    if not hasattr(self, "commands"):
        raise AttributeError("The object does not have a 'commands' attribute")

    # Retrieve the command
    try:
        command = self.commands[command_name]
    except KeyError:
        raise KeyError(f"Command '{command_name}' not found")

    # Retrieve the options mapping from the command
    options = getattr(command, "options", None)
    if options is None:
        raise AttributeError(f"Command '{command_name}' has no 'options' attribute")

    # Ensure options is a mapping
    if not hasattr(options, "get"):
        raise TypeError(f"The 'options' attribute of command '{command_name}' is not a mapping")

    # Retrieve the option specification
    spec = options.get(argument_name)
    if spec is None:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")

    return spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_flags = {'-q', '--quiet', '-s', '--silent', '--no-output', '--no-logging'}
    result = []
    if args is None:
        return result
    if isinstance(args, str):
        args = [args]
    try:
        for arg in args:
            if not isinstance(arg, str):
                continue
            if arg in silent_flags:
                result.append(arg)
            else:
                for flag in silent_flags:
                    if arg.startswith(flag + '='):
                        result.append(arg)
                        break
    except Exception:
        return result
    return result

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Ensure args is a dictionary
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")
    # Retrieve the list/set/tuple of required argument names
    try:
        required = getattr(self, "required_args")
    except AttributeError:
        raise AttributeError("The object does not have a 'required_args' attribute.")
    if not isinstance(required, (list, set, tuple)):
        raise TypeError(f"required_args must be a list, set, or tuple, got {type(required).__name__}")
    # Find any missing required arguments
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []

    # Normalise args to a dict for lookup
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception:
            args = {}

    # Prepare a safe namespace for evaluating conditions
    local_vars = {"command_name": command_name}
    local_vars.update(args)

    if not options_spec:
        return required

    for spec in options_spec:
        if not isinstance(spec, dict):
            continue
        if "required_when" not in spec:
            continue

        cond = spec["required_when"]
        try:
            # If the condition is a callable, call it with args
            if callable(cond):
                cond_result = cond(args)
            else:
                # Evaluate the condition string in the local namespace
                cond_result = eval(cond, {}, local_vars)
        except Exception:
            # If evaluation fails, treat the condition as not matched
            cond_result = False

        if cond_result:
            name = spec.get("name")
            if name:
                required.append(name)

    return required

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Can be a single numeric value, a list/tuple/set of numeric values,
                 or a dictionary mapping names to numeric values.
    :return: True if all values are within the bounds defined by self.min and self.max.
    :raises AttributeError: If the object does not have 'min' and 'max' attributes.
    :raises ValueError: If min > max or any value is out of bounds.
    :raises TypeError: If args is None or contains non-numeric values.
    """
    # Ensure the object has min and max attributes
    if not hasattr(self, 'min') or not hasattr(self, 'max'):
        raise AttributeError("Object must have 'min' and 'max' attributes.")
    min_val = self.min
    max_val = self.max
    if min_val > max_val:
        raise ValueError(f"Minimum value {min_val} is greater than maximum value {max_val}.")

    def _check(val, name='value'):
        if not isinstance(val, (int, float)):
            raise TypeError(f"Argument '{name}' must be a number, got {type(val).__name__}.")
        if val < min_val or val > max_val:
            raise ValueError(f"Argument '{name}' with value {val} is out of bounds [{min_val}, {max_val}].")

    if args is None:
        raise TypeError("Argument 'args' cannot be None.")

    # Handle dictionary of named arguments
    if isinstance(args, dict):
        for key, val in args.items():
            _check(val, name=key)
    # Handle iterable of values (list, tuple, set)
    elif isinstance(args, (list, tuple, set)):
        for idx, val in enumerate(args):
            _check(val, name=f'index {idx}')
    # Handle single numeric value
    else:
        _check(args, name='value')

    return True

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: The updated dictionary
        """
        # Validate input types
        if vars_dict is None:
            raise ValueError("vars_dict cannot be None")
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        # If no extra_vars provided, simply return the original dict
        if not extra_vars:
            return vars_dict

        # Ensure extra_vars is iterable
        if not isinstance(extra_vars, (list, tuple)):
            # If it's a single string, wrap it in a list
            if isinstance(extra_vars, str):
                extra_vars = [extra_vars]
            else:
                raise TypeError(f"extra_vars must be a list or tuple of strings, got {type(extra_vars).__name__}")

        for item in extra_vars:
            # Skip non-string items
            if not isinstance(item, str):
                continue
            # Skip empty strings
            if not item.strip():
                continue
            # Split on the first '='
            if "=" not in item:
                continue
            key, value = item.split("=", 1)
            key = key.strip()
            value = value.strip()
            if not key:
                continue
            # Remove surrounding quotes from value if present
            if (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
                value = value[1:-1]
            # Assign to the dictionary (override if key exists)
            vars_dict[key] = value

        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Basic validation
    if ir_workspace is None:
        raise ValueError("ir_workspace must not be None")
    if ir_plugin is None:
        raise ValueError("ir_plugin must not be None")
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if verbose is not None and not isinstance(verbose, int):
        raise TypeError("verbose must be an integer or None")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise TypeError("extra_vars must be a dict or None")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise TypeError("ansible_args must be a dict or None")

    # Import required modules lazily
    subprocess = __import__('subprocess')
    json = __import__('json')
    os = __import__('os')

    # Ensure playbook exists
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook '{playbook_path}' does not exist")

    # Build command
    cmd = ['ansible-playbook', playbook_path]

    # Verbosity
    if verbose:
        cmd.extend(['-' + 'v' * verbose])

    # Extra vars
    if extra_vars:
        try:
            ev_str = json.dumps(extra_vars)
        except Exception as exc:
            raise ValueError(f"Failed to serialize extra_vars: {exc}") from exc
        cmd.extend(['--extra-vars', ev_str])

    # Additional ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            flag = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
                # if False, skip
            elif isinstance(value, (list, tuple)):
                for v in value:
                    cmd.append(f"{flag}={v}")
            else:
                cmd.append(f"{flag}={value}")

    # Execute command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False
        )
    except OSError as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    # Optionally print output if verbose level is high
    if verbose and verbose >= 2:
        print("STDOUT:")
        print(result.stdout)
        print("STDERR:")
        print(result.stderr)

    return result

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    if not isinstance(plugin_dir, (str, bytes, os.PathLike)):
        raise TypeError("plugin_dir must be a path-like object or string")

    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory not found: {plugin_dir}")

    # Find the spec file
    spec_filenames = ["plugin.yaml", "plugin.yml", "plugin.json"]
    spec_path = None
    for name in spec_filenames:
        candidate = os.path.join(plugin_dir, name)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if spec_path is None:
        raise FileNotFoundError(
            f"No plugin spec file found in {plugin_dir}. "
            f"Expected one of: {', '.join(spec_filenames)}"
        )

    # Load the spec
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            content = f.read()
    except Exception as exc:
        raise IOError(f"Failed to read spec file {spec_path}: {exc}") from exc

    try:
        if spec_path.lower().endswith(".json"):
            data = json.loads(content)
        else:
            if yaml is None:
                raise ImportError("PyYAML is required to parse YAML plugin specs")
            data = yaml.safe_load(content)
    except Exception as exc:
        raise ValueError(f"Failed to parse plugin spec {spec_path}: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError(f"Plugin spec root must be a mapping, got {type(data).__name__}")

    # Helper to flatten nested dicts/lists
    def _flatten(obj, parent_key=""):
        flat = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}.{k}" if parent_key else str(k)
                flat.update(_flatten(v, new_key))
        elif isinstance(obj, list):
            for idx, item in enumerate(obj):
                new_key = f"{parent_key}.{idx}" if parent_key else str(idx)
                flat.update(_flatten(item, new_key))
        else:
            flat[parent_key] = obj
        return flat

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os
        env_var = 'CONFIG_PATH'
        if env_var in os.environ:
            return
        # Determine the config path: use attribute if present, otherwise a sensible default
        path = getattr(self, 'config_path', None)
        if not path:
            path = '/etc/myapp/config.yaml'
        os.environ[env_var] = str(path)
    except Exception as e:
        raise RuntimeError(f"Failed to inject config environment variable: {e}") from e

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to the main entry point.

    :param root_subparsers: the subparser object to extend.
    """
    if root_subparsers is None:
        raise TypeError("root_subparsers cannot be None")
    try:
        spec_parser = root_subparsers.add_parser('spec', help='Spec command')
    except AttributeError as e:
        raise TypeError("root_subparsers must have an add_parser method") from e
    except Exception as e:
        raise RuntimeError(f"Failed to add spec subparser: {e}") from e

    try:
        spec_parser.add_argument('-f', '--file', type=str, required=True,
                                 help='Path to the spec file')
        spec_parser.add_argument('-o', '--output', type=str, default='output.txt',
                                 help='Output file path')
        spec_parser.add_argument('-v', '--verbose', action='store_true',
                                 help='Enable verbose output')
    except Exception as e:
        raise RuntimeError(f"Failed to add arguments to spec subparser: {e}") from e

    def _not_implemented(args):
        raise NotImplementedError("Spec command is not implemented")

    try:
        spec_parser.set_defaults(func=_not_implemented)
    except Exception as e:
        raise RuntimeError(f"Failed to set defaults for spec subparser: {e}") from e

    return None
